head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil25900";
scwin.modifiyDate = "N";
scwin.result = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_nowVars();
        scwin.init_attrReals();
        scwin.init_conds();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil25900.onpageload' });
    }
};

/**
 * @method
 * @name init_nowVars
 * @description 현재 시각 파생값 충전 — as-is JSP 계산분(서버 데이터 아님)
 * @returns {void}
 * @hidden N
 */
scwin.init_nowVars = function () {
    const pc = $c.util.getComponent('dma_pageContext');
    if (!pc || !pc.set || !pc.get) { return; }
    if (!pc.get("sysYear")) { pc.set("sysYear", $c.date.getServerDateTime("yyyy")); }
};

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — listStatCd

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "td_16", attr: "__html", fn: function () { return ([String(String((dma_pageContext.get("sysYear") ?? ""))), String((String((dma_pageContext.get("sysYear") ?? "")) - 1))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? ("『배당기준일자 신고』작성하는 화면입니다.<br/> <span style=\"color:red\">" + String(String((dma_pageContext.get("sysYear") ?? ""))) + "</span>년도 배당기준일 신고는 반드시 <span style=\"color:red\">작성하기</span> 버튼을 눌러서 제출해주시기 바랍니다. (※ " + String((String((dma_pageContext.get("sysYear") ?? "")) - 1)) + "년도 신고내용 수정·제출 금지)") : ''); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "btn_goWrite", fn: function(){ return ((dma_pageContext.get("listStatCd") ?? "") ==='Y'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_goWrite_onclick
 * @description 「작성하기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_goWrite_onclick = async function(e){
    try {
        await scwin.goWrite()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil25900.btn_goWrite_onclick' }); }
};

/**
 * @method
 * @name grd_dividendDateList_oncellclick
 * @description grd_dividendDateList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_dividendDateList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_dividendDateList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_dividendDateList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        await scwin.goView(r["bzProcsNo"], r["basYy"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_dividendDateList.oncellclick' });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_goWrite
 * @description go Write 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_goWrite = async function () {
    const sbmOptions = {
        id: "tx_fn_goWrite",
        method: "post",
        action: "/account/dividendBaseDate.do",
        ref: "dma_goWriteReq",
        target: "dlt_dividendDateList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_goView
 * @description go View 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_goView = async function () {
    const sbmOptions = {
        id: "tx_fn_goView",
        method: "post",
        action: "/account/dividendBaseDate.do",
        ref: "dma_goViewReq",
        target: "dlt_dividendDateList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_modifiyDate
 * @description modifiy Date 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_modifiyDate = async function () {
    const sbmOptions = {
        id: "tx_fn_modifiyDate",
        method: "post",
        action: "/account/dividendBaseDate.do",
        ref: "dma_modifiyDateReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_load_list
 * @description load list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/account/dividendBaseDate.do",
        ref: "dma_loadListReq",
        target: "dlt_dividendDateList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name goWrite
 * @description go Write 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goWrite = async function () {
    await scwin.selectModifiyDate();
    if (scwin.modifiyDate === "N") {
        await $c.win.alert("작성기간이 아닙니다.");
        return;
    }
    if (scwin.modifiyDate === "U") {
        await $c.win.alert("작성중인 배당기준일자 신고가 있습니다.");
        return;
    }
    $c.util.getComponent('ipt_method').setValue("dividendDateModifiy");
    $c.util.getComponent('ipt_status').setValue("R");
    const nr = await scwin.tx_fn_goWrite();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil25910/jldfil25910.xml", { "method": "dividendDateModifiy", "status": "R" });
    }
};

/**
 * @method
 * @name goView
 * @description go View 처리
 * @param {*} ipt_bzProcsNo ipt_bzProcsNo
 * @param {*} basYear basYear
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goView = async function (ipt_bzProcsNo, basYear) {
    $c.util.getComponent('ipt_method').setValue("dividendDateModifiy");
    $c.util.getComponent('ipt_status').setValue(await scwin.selectModifiyDate());
    $c.util.getComponent('ipt_bzProcsNo').setValue(ipt_bzProcsNo);
    const nr = await scwin.tx_fn_goView();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil25910/jldfil25910.xml", { "method": "dividendDateModifiy", "bzProcsNo": ipt_bzProcsNo });
    }
};

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)

/**
 * @method
 * @name modifiyDateDone
 * @description modifiy Date Done 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.modifiyDateDone = function (data) {
    scwin.result = (typeof data === "string" ? JSON.parse(data) : data);
    scwin.modifiyDate = scwin.result.checkModifiyDate;
};

/**
 * @method
 * @name selectModifiyDate
 * @description select Modifiy Date 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.selectModifiyDate = async function () {
    const r = await scwin.tx_fn_modifiyDate();
    try {
        scwin.modifiyDateDone.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldfil25900.fn_modifiyDate' });
    }
    return r;
};
